function deposit(
    address yieldToken,
    uint256 amount,
    address recipient
) external override lock returns (uint256) {
    revert();
}

/// @inheritdoc IAlchemistV2Actions
function depositUnderlying(
    address yieldToken,
    uint256 amount,
    address recipient,
    uint256 minimumAmountOut
) external override lock returns (uint256) {
    revert();
}

/// @inheritdoc IAlchemistV2Actions
function withdraw(
    address yieldToken,
    uint256 shares,
    address recipient
) external override lock returns (uint256) {
    revert();
}

/// @inheritdoc IAlchemistV2Actions
function withdrawFrom(
    address owner,
    address yieldToken,
    uint256 shares,
    address recipient
) external override lock returns (uint256) {
    revert();
}

/// @inheritdoc IAlchemistV2Actions
function withdrawUnderlying(
    address yieldToken,
    uint256 shares,
    address recipient,
    uint256 minimumAmountOut
) external override lock returns (uint256) {
    revert();
}

/// @inheritdoc IAlchemistV2Actions
function withdrawUnderlyingFrom(
    address owner,
    address yieldToken,
    uint256 shares,
    address recipient,
    uint256 minimumAmountOut
) external override lock returns (uint256) {
    revert();
}

/// @inheritdoc IAlchemistV2Actions
function mint(uint256 amount, address recipient) external override lock {
    revert();
}

/// @inheritdoc IAlchemistV2Actions
function mintFrom(
    address owner,
    uint256 amount,
    address recipient
) external override lock {
    revert();
}

/// @inheritdoc IAlchemistV2Actions
function burn(uint256 amount, address recipient) external override lock returns (uint256) {
    revert();
}

/// @inheritdoc IAlchemistV2Actions
function repay(address underlyingToken, uint256 amount, address recipient) external override lock returns (uint256) {
    revert();
}

/// @inheritdoc IAlchemistV2Actions
function liquidate(
    address yieldToken,
    uint256 shares,
    uint256 minimumAmountOut
) external override lock returns (uint256) {
    revert();
}
